using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to query (e.g. \"/users/1\")")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a concise summary of the provided text.")]
    public static ChatMessage[] Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemMessage = style switch
        {
            "detailed" => "You are an expert summarizer. Provide a thorough summary preserving key details and nuance.",
            "bullet-points" => "You are an expert summarizer. Provide a summary as concise bullet points.",
            _ => "You are an expert summarizer. Provide a brief, concise summary in 2-3 sentences."
        };

        return
        [
            new(ChatRole.User, $"{systemMessage}\n\nPlease summarize the following text:\n\n{text}")
        ];
    }
}

